package com.companages.service;
import com.companages.dto.*; import com.companages.entity.*; import com.companages.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.stream.Collectors;
@Service public class DashboardService {private final CurrentUserService current;private final OrganizationRepository organizations;private final MemberRepository members;private final PositionRepository positions;private final AssignmentRepository assignments;private final TeamRepository teams;private final InvitationRepository invitations;private final OrganizationAccessService access;public DashboardService(CurrentUserService c,OrganizationRepository o,MemberRepository m,PositionRepository p,AssignmentRepository a,TeamRepository t,InvitationRepository i,OrganizationAccessService x){current=c;organizations=o;members=m;positions=p;assignments=a;teams=t;invitations=i;access=x;}
 @Transactional(readOnly=true)public DashboardResponse get(){List<Organization> orgs=organizations.findAllForUser(current.get().getId());long memberCount=orgs.stream().mapToLong(o->members.countByOrganizationId(o.getId())).sum();long positionCount=orgs.stream().mapToLong(o->positions.countByOrganizationId(o.getId())).sum();long assignmentCount=orgs.stream().mapToLong(o->assignments.findAllByOrganizationIdOrderByCreatedAtDesc(o.getId()).size()).sum();List<com.companages.dto.MemberDtos.Response> recent=orgs.stream().flatMap(o->members.findTop5ByOrganizationIdOrderByCreatedAtDesc(o.getId()).stream()).sorted(Comparator.comparing(Member::getCreatedAt).reversed()).limit(5).map(Mappers::member).toList();return new DashboardResponse(orgs.size(),memberCount,positionCount,assignmentCount,recent);}
 @Transactional(readOnly=true)public OrganizationDashboardResponse get(Long oid){access.requireMember(oid);List<Member> all=members.findAllByOrganizationIdOrderByName(oid);Map<String,Long> byTeam=all.stream().collect(Collectors.groupingBy(m->m.getTeam()==null?"Unassigned":m.getTeam().getName(),LinkedHashMap::new,Collectors.counting()));Map<String,Long> byPosition=all.stream().collect(Collectors.groupingBy(m->m.getPosition()==null?"Unassigned":m.getPosition().getName(),LinkedHashMap::new,Collectors.counting()));Map<String,Long> byStatus=all.stream().collect(Collectors.groupingBy(m->m.getStatus().name(),LinkedHashMap::new,Collectors.counting()));Map<YearMonth,Long> joined=all.stream().collect(Collectors.groupingBy(m->YearMonth.from(m.getJoinedAt()==null?m.getCreatedAt().atZone(ZoneOffset.UTC):m.getJoinedAt()),TreeMap::new,Collectors.counting()));Map<String,Long> growth=new LinkedHashMap<>();long running=0;for(var entry:joined.entrySet()){running+=entry.getValue();growth.put(entry.getKey().format(DateTimeFormatter.ofPattern("MMM yyyy")),running);}return new OrganizationDashboardResponse(all.size(),members.countByOrganizationIdAndStatus(oid,RecordStatus.ACTIVE),teams.countByOrganizationIdAndStatus(oid,RecordStatus.ACTIVE),positions.countByOrganizationId(oid),invitations.countByOrganizationIdAndStatus(oid,InvitationStatus.PENDING),members.findTop5ByOrganizationIdOrderByCreatedAtDesc(oid).stream().map(Mappers::member).toList(),byTeam,byPosition,byStatus,growth);}}
